        apkgs = {p['id']: p['resolvedVersion'] for p in af.get('topLevelPackages',[])}
        if bpkgs == apkgs:
            print(f'{name}: all versions match')
        else:
            print(f'{name}: MISMATCH baseline={bpkgs} after={apkgs}')
"

